using System.Security.Claims;
using Ex_SurveyApp_api.Controllers;
using Ex_SurveyApp_api.Data;
using Ex_SurveyApp_api.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

internal static class InspectionPlanningApiChecks
{
    private static int checks;
    private static void Check(bool value,string name){checks++;if(!value)throw new InvalidOperationException($"Inspection planning API check failed: {name}");}
    private static InspectionPlanningController Controller(SurveyDbContext db,Guid actor,string role)
    {
        var c=new InspectionPlanningController(db);var identity=new ClaimsIdentity(new[]{new Claim(ClaimTypes.NameIdentifier,actor.ToString()),new Claim(ClaimTypes.Role,role)},"test",ClaimTypes.Name,ClaimTypes.Role);c.ControllerContext=new ControllerContext{HttpContext=new DefaultHttpContext{User=new ClaimsPrincipal(identity)}};return c;
    }
    private static T Value<T>(IActionResult result)=>result switch{OkObjectResult ok when ok.Value is T value=>value,CreatedAtActionResult created when created.Value is T value=>value,_=>throw new InvalidOperationException($"Unexpected response {result.GetType().Name}")};
    public static async Task Run()
    {
        var options=new DbContextOptionsBuilder<SurveyDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options;await using var db=new SurveyDbContext(options);
        var manager=new User{Email="plan-manager@test.invalid",DisplayName="Manager",PasswordHash="test",Role=UserRole.Manager,ApprovalStatus=ApprovalStatus.Approved};var surveyor=new User{Email="plan-surveyor@test.invalid",DisplayName="Surveyor",PasswordHash="test",Role=UserRole.Surveyor,ApprovalStatus=ApprovalStatus.Approved};var qc=new User{Email="plan-qc@test.invalid",DisplayName="QC",PasswordHash="test",Role=UserRole.Qc,ApprovalStatus=ApprovalStatus.Approved};var inspectionLead=new User{Email="plan-lead@test.invalid",DisplayName="Inspection Lead",PasswordHash="test",Role=UserRole.Qc,ApprovalStatus=ApprovalStatus.Approved};db.Users.AddRange(manager,surveyor,qc,inspectionLead);
        var project=new Project{ProjectName="Synthetic Campaign",Sector="Synthetic",JobNo="PLAN-TEST",Location="Test",VesselOrSiteName="Test Site",CreatedByUserId=manager.Id,AssignedSurveyorId=surveyor.Id,AssignedQcId=qc.Id};db.Projects.Add(project);var equipment=Enumerable.Range(1,10).Select(i=>new AreaEquipment{ProjectId=project.Id,AreaId=Guid.NewGuid(),SequenceNo=i,TagNumber=$"EQ-{i:00}",Type=i%2==0?"Motor":"Junction box",CreatedByUserId=manager.Id}).ToArray();db.AreaEquipment.AddRange(equipment);await db.SaveChangesAsync();
        var managerApi=Controller(db,manager.Id,"Manager");var created=await managerApi.CreateCampaign(new(project.Id,"Synthetic 90/10","SYN-01",new DateOnly(2026,1,1),new DateOnly(2026,12,31),inspectionLead.Id),default);var campaign=Value<InspectionCampaign>(created);Check(campaign.ProjectId==project.Id&&campaign.InspectionLeadUserId==inspectionLead.Id,"campaign preserves project relationship and records selected Inspection Lead");
        await managerApi.ConfigureAllocation(campaign.Id,new(90,10,5,AllocationRoundingRule.Nearest),default);
        var annual=await managerApi.SetAnnualList(campaign.Id,new(2026,equipment.Select(x=>x.Id).ToList()),default);Check(annual is OkObjectResult,"annual equipment list saved with project equipment IDs");
        var qcApi=Controller(db,qc.Id,"Qc");var leadApi=Controller(db,inspectionLead.Id,"Qc");Check(Value<System.Collections.IEnumerable>(await leadApi.Campaigns(default)).Cast<object>().Any(),"appointed campaign Inspection Lead can discover the campaign");Check(await qcApi.ApproveAllocation(campaign.Id,new("Not the appointed Lead"),default) is ForbidResult,"project QC who is not the campaign Inspection Lead cannot approve allocation");var approved=await leadApi.ApproveAllocation(campaign.Id,new("Synthetic approved"),default);Check(approved is OkObjectResult,"appointed QC Inspection Lead can approve allocation");
        var list=await db.CampaignAnnualLists.SingleAsync(x=>x.CampaignId==campaign.Id);Check(list.PlannedCloseCount==9&&list.PlannedDetailedCount==1,"10 item allocation calculates 9 Close and 1 Detailed");
        Check(await managerApi.CreateRecurrence(campaign.Id,new(list.Id,InspectionType.Close,12,new DateOnly(2027,1,1)),default) is OkObjectResult&&await db.InspectionRecurrences.AnyAsync(x=>x.CampaignId==campaign.Id&&x.EveryMonths==12),"future contract recurrence schedule is retained");
        var preview=await managerApi.PreviewSampling(campaign.Id,list.Id,new(SamplingMethod.Random,1,222,"Synthetic sample",null,null),default);var sampling=Value<object>(preview);var previewId=(Guid)sampling.GetType().GetProperty("Id")!.GetValue(sampling)!;Guid[] selectedIds=(Guid[])sampling.GetType().GetProperty("EquipmentIds")!.GetValue(sampling)!;
        Check(selectedIds.Length==1,"random sample uses configured detailed count");Check(await qcApi.ApproveSampling(previewId,new("Not the appointed Lead"),default) is ForbidResult,"non-lead QC cannot approve the campaign sample");var sampleApproval=await leadApi.ApproveSampling(previewId,new("Approved"),default);Check(sampleApproval is OkObjectResult&&await db.SamplingApprovals.AnyAsync(x=>x.Id==previewId&&x.IsFrozen),"appointed Inspection Lead approval freezes selected sample");
        var priorRevision=(int)sampling.GetType().GetProperty("CampaignRevision")!.GetValue(sampling)!;Check(await managerApi.EditCampaign(campaign.Id,new("Synthetic 90/10 revised","SYN-01",new DateOnly(2026,1,1),new DateOnly(2026,12,31),"Sampling methodology review",inspectionLead.Id),default) is OkObjectResult,"campaign edit creates a planning revision");Check(await db.SamplingApprovals.AnyAsync(x=>x.Id==previewId&&x.CampaignRevision==priorRevision&&x.IsFrozen),"previous revision sample remains frozen in history");await managerApi.ConfigureAllocation(campaign.Id,new(90,10,5,AllocationRoundingRule.Nearest),default);Check(await leadApi.ApproveAllocation(campaign.Id,new("Approve revised allocation"),default) is OkObjectResult,"revised allocation requires and accepts a new lead approval");
        var revisedPreview=await managerApi.PreviewSampling(campaign.Id,list.Id,new(SamplingMethod.Random,1,223,"Revised sample",null,null),default);var revised=Value<object>(revisedPreview);var revisedPreviewId=(Guid)revised.GetType().GetProperty("Id")!.GetValue(revised)!;var revisedIds=(Guid[])revised.GetType().GetProperty("EquipmentIds")!.GetValue(revised)!;var revisedNumber=(int)revised.GetType().GetProperty("CampaignRevision")!.GetValue(revised)!;Check(revisedNumber>priorRevision,"new sample is bound to the new campaign revision");Check(await leadApi.ApproveSampling(revisedPreviewId,new("Approve revised sample"),default) is OkObjectResult&&await db.SamplingApprovals.CountAsync(x=>x.AnnualListId==list.Id&&x.IsFrozen)==2,"new revision receives its own frozen sample while prior sample is retained");selectedIds=revisedIds;
        var detailed=await managerApi.CreatePackage(campaign.Id,new("WP-D","Test Site","Area 1","R1",new DateOnly(2026,1,1),new DateOnly(2026,1,31),new[]{new PlannedEquipmentTask(selectedIds[0],InspectionType.Detailed,null,1,"Normal",null,null,null,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow.AddDays(3))}.ToList()),default);
        Check(detailed is CreatedAtActionResult&&await db.InspectionTasks.AnyAsync(x=>x.PlannedGrade==InspectionType.Detailed&&x.AssignedUserId==surveyor.Id&&x.ScheduledAt.HasValue&&x.DueAt.HasValue),"work package task retains grade, schedule, due date and project Surveyor assignment");
        Check(await managerApi.SetCampaignStatus(campaign.Id,new(CampaignStatus.InProgress,"Package mobilized"),default) is OkObjectResult,"campaign can enter execution after approved allocation and package creation");Check(await managerApi.SetCampaignStatus(campaign.Id,new(CampaignStatus.Completed,"Premature close"),default) is ConflictObjectResult,"campaign cannot close while work package tasks remain active");
        var secondSurveyor=new User{Email="plan-surveyor-2@test.invalid",DisplayName="Second Surveyor",PasswordHash="test",Role=UserRole.Surveyor,ApprovalStatus=ApprovalStatus.Approved};db.Users.Add(secondSurveyor);await db.SaveChangesAsync();var detailedTask=await db.InspectionTasks.SingleAsync(x=>x.PlannedGrade==InspectionType.Detailed);
        Check(await managerApi.Reassign(detailedTask.Id,new(secondSurveyor.Id,"Rotation change"),default) is OkObjectResult&&await db.InspectionTaskAssignmentEvents.AnyAsync(x=>x.InspectionTaskId==detailedTask.Id&&x.PreviousUserId==surveyor.Id&&x.NewUserId==secondSurveyor.Id),"inspector reassignment retains an audit event");
        var reassignedSurveyor=Controller(db,secondSurveyor.Id,"Surveyor");Check(await reassignedSurveyor.Inaccessible(detailedTask.Id,new("Access platform not released"),default) is OkObjectResult,"reassigned Surveyor can record inaccessible carry-forward reason");
        Check(Value<System.Collections.IEnumerable>(await reassignedSurveyor.Campaigns(default)).Cast<object>().Any(),"assigned Surveyor can discover the campaign through task ownership");
        var progress=await reassignedSurveyor.Progress(campaign.Id,default);var progressValue=((OkObjectResult)progress).Value!;var inaccessibleCount=(int)progressValue.GetType().GetProperty("Inaccessible")!.GetValue(progressValue)!;
        Check(inaccessibleCount==1,"progress recalculates inaccessible work from carried-forward tasks");
        var duplicate=await managerApi.CreatePackage(campaign.Id,new("WP-DUP","Test Site","Area 1","R1",null,null,new[]{new PlannedEquipmentTask(selectedIds[0],InspectionType.Detailed,null,1,null,null,null,null,null,null)}.ToList()),default);Check(duplicate is ConflictObjectResult,"duplicate active equipment task is rejected");
        var unrelated=Controller(db,Guid.NewGuid(),"Manager");Check(await unrelated.CreateCampaign(new(project.Id,"Unauthorized","NO-ACCESS",new DateOnly(2026,1,1),new DateOnly(2026,12,31)),default) is NotFoundResult,"manager cannot create a campaign for an unassigned project");
        var closeIds=equipment.Select(x=>x.Id).Where(x=>x!=selectedIds[0]).ToArray();var close=await managerApi.CreatePackage(campaign.Id,new("WP-C","Test Site","Area 1","R1",null,null,closeIds.Select((x,i)=>new PlannedEquipmentTask(x,InspectionType.Close,null,i+1,"Normal",null,null,null,null,null)).ToList()),default);Check(close is CreatedAtActionResult,"Close tasks can be assigned independently from Detailed sample");
        Console.WriteLine($"Inspection planning API checks passed: {checks} assertions. Synthetic in-memory persistence only.");
    }
}
